import React from "react";
import {Link} from "gatsby";
import {GatsbyImage, getImage} from "gatsby-plugin-image";

function formatDate(dateString) {
  if (!dateString) return null;
  const d = new Date(dateString);
  return d.toLocaleDateString('en-US', {year: 'numeric', month: 'short', day: 'numeric'});
}

function withTrailingSlash(urlPath) {
  if (!urlPath) return '/';
  if (urlPath === '/') return '/';
  return urlPath.endsWith('/') ? urlPath : `${urlPath}/`;
}

const BlogPostCard = ({postDetails, timeToRead}) => {
  const {slug, headerImage, category, title, author, shortDescription, publishedAt} = postDetails;
  const imageObject = getImage(headerImage.childImageSharp.gatsbyImageData)
  const postUrl = withTrailingSlash(slug);

  return (
    <article className="post-card">
      <Link className="post-card-image-link" to={postUrl}>
        <div className="post-card-image">
          <div className="gatsby-image-wrapper">
            <GatsbyImage alt={title} image={imageObject}/>
          </div>
        </div>
      </Link>
      <div className="post-card-content">
        <Link className="post-card-content-link post-card-details" to={postUrl}>
          <header className="post-card-header">
            <span className="category">{category}</span>
            <h2 className="post-card-title">{title}</h2>
          </header>
          <section className="post-card-body">
            <p>{shortDescription}</p>
          </section>
        </Link>
        <footer className="post-card-meta">
          <ul className="post-card-meta-list">
            <li>
              <div className="author-name">@{author}</div>
            </li>
            {publishedAt && (
              <li>
                <time className="publish-date" dateTime={publishedAt}>{formatDate(publishedAt)}</time>
              </li>
            )}
          </ul>
          <span className="read-time">{timeToRead || 1} min read</span>
        </footer>
      </div>
    </article>
  )
}
export default BlogPostCard;
