import React from 'react'
import {graphql} from "gatsby"
import {Helmet} from "react-helmet"
import {MDXRenderer} from "gatsby-plugin-mdx";
import {GatsbyImage, getImage} from "gatsby-plugin-image";
import Navbar from "../components/App/Navbar";
import Layout from "../components/App/Layout";
import HowCanWeHelpBanner from "../components/Index/HowCanWeHelpBanner";
import Footer from '../components/App/Footer'
import SecondaryPageHeader from "../components/SecondaryPageHeader";
import '../assets/css/blog-homepage.css';
import BlogPostCard from "../components/BlogPostCard";

const SITE_URL = 'https://salspotsoftware.com';
const SITE_NAME = 'Salspot Software';

function withTrailingSlash(urlPath) {
  if (!urlPath) return '/';
  if (urlPath === '/') return '/';
  return urlPath.endsWith('/') ? urlPath : `${urlPath}/`;
}

function formatDate(dateString) {
  if (!dateString) return null;
  const d = new Date(dateString);
  return d.toLocaleDateString('en-US', {year: 'numeric', month: 'long', day: 'numeric'});
}

function BlogPostSEO({frontmatter, timeToRead, excerpt, siteUrl}) {
  const {title, shortDescription, slug, category, author, publishedAt, headerImage} = frontmatter;
  const description = shortDescription || excerpt;
  const canonical = `${siteUrl}${withTrailingSlash(slug)}`;
  const imageUrl = headerImage?.childImageSharp?.gatsbyImageData?.images?.fallback?.src
    ? `${siteUrl}${headerImage.childImageSharp.gatsbyImageData.images.fallback.src}`
    : null;

  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Article',
    headline: title,
    description,
    author: {'@type': 'Person', name: author},
    publisher: {
      '@type': 'Organization',
      name: SITE_NAME,
      url: siteUrl,
    },
    mainEntityOfPage: {'@type': 'WebPage', '@id': canonical},
    datePublished: publishedAt,
    ...(imageUrl && {image: imageUrl}),
    ...(category && {articleSection: category}),
    ...(timeToRead && {timeRequired: `PT${timeToRead}M`}),
  };

  return (
    <Helmet>
      <title>{`${title} | ${SITE_NAME} Blog`}</title>
      <meta name="description" content={description}/>
      <link rel="canonical" href={canonical}/>

      <meta property="og:type" content="article"/>
      <meta property="og:title" content={title}/>
      <meta property="og:description" content={description}/>
      <meta property="og:url" content={canonical}/>
      <meta property="og:site_name" content={SITE_NAME}/>
      {imageUrl && <meta property="og:image" content={imageUrl}/>}
      {publishedAt && <meta property="article:published_time" content={publishedAt}/>}
      {author && <meta property="article:author" content={author}/>}
      {category && <meta property="article:section" content={category}/>}

      <meta name="twitter:card" content="summary_large_image"/>
      <meta name="twitter:title" content={title}/>
      <meta name="twitter:description" content={description}/>
      {imageUrl && <meta name="twitter:image" content={imageUrl}/>}

      <script type="application/ld+json">{JSON.stringify(jsonLd)}</script>
    </Helmet>
  );
}

function BlogListingSEO({posts, siteUrl}) {
  const title = 'Blog | Salspot Software';
  const description = "Actionable insights on engineering, design, process and strategy from the Salspot Software team.";
  const canonical = `${siteUrl}/blog/`;

  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Blog',
    name: title,
    description,
    url: canonical,
    publisher: {'@type': 'Organization', name: SITE_NAME, url: siteUrl},
    blogPost: posts.map(({node}) => ({
      '@type': 'BlogPosting',
      headline: node.frontmatter.title,
      url: `${siteUrl}${withTrailingSlash(node.frontmatter.slug)}`,
      datePublished: node.frontmatter.publishedAt,
      author: {'@type': 'Person', name: node.frontmatter.author},
      description: node.frontmatter.shortDescription,
    })),
  };

  return (
    <Helmet>
      <title>{title}</title>
      <meta name="description" content={description}/>
      <link rel="canonical" href={canonical}/>

      <meta property="og:type" content="website"/>
      <meta property="og:title" content={title}/>
      <meta property="og:description" content={description}/>
      <meta property="og:url" content={canonical}/>
      <meta property="og:site_name" content={SITE_NAME}/>

      <meta name="twitter:card" content="summary_large_image"/>
      <meta name="twitter:title" content={title}/>
      <meta name="twitter:description" content={description}/>

      <script type="application/ld+json">{JSON.stringify(jsonLd)}</script>
    </Helmet>
  );
}

export default function BlogHomepage({data}) {
  const isBlogPost = data?.mdx?.frontmatter?.key === 'blog-post';
  const articleImage = getImage(data?.mdx?.frontmatter?.headerImage?.childImageSharp?.gatsbyImageData);

  return (
    <Layout>
      <Navbar className="navbar-fixed-top white-page"/>
      {isBlogPost ? (
        <>
          <BlogPostSEO
            frontmatter={data.mdx.frontmatter}
            timeToRead={data.mdx.timeToRead}
            excerpt={data.mdx.excerpt}
            siteUrl={SITE_URL}
          />
          <SecondaryPageHeader
            smallTitle='Blog'
            title={data.mdx.frontmatter.title}
            classNames='blog'
            headlineClassNames='col-xl-8 col-md-8 col-sm-8 col-xs-12 row flex-column'
            subtext={data.mdx.frontmatter.shortDescription}
          />
          <section className="post-body blog blog-article-wrapper">
            <div className="container">
              <div className="row">
                <article className="blog-article-content">
                  {articleImage && (
                    <div className="blog-article-hero">
                      <GatsbyImage alt={data.mdx.frontmatter.title} image={articleImage}/>
                    </div>
                  )}
                  <div className="blog-article-meta">
                    <span className="category">{data.mdx.frontmatter.category}</span>
                    {data.mdx.frontmatter.publishedAt && (
                      <time className="publish-date" dateTime={data.mdx.frontmatter.publishedAt}>
                        {formatDate(data.mdx.frontmatter.publishedAt)}
                      </time>
                    )}
                    <span className="author-name">@{data.mdx.frontmatter.author}</span>
                    {data.mdx.timeToRead && (
                      <span className="read-time">{data.mdx.timeToRead} min read</span>
                    )}
                  </div>
                  <div className="blog-article-prose">
                    <MDXRenderer>{data.mdx.body}</MDXRenderer>
                  </div>
                </article>
              </div>
            </div>
          </section>
        </>
      ) : (
        <>
          <BlogListingSEO posts={data.allMdx.edges} siteUrl={SITE_URL}/>
          <SecondaryPageHeader smallTitle='Blog' title='Ideas are great. Results are better.' classNames='blog'
                               headlineClassNames='col-xl-8 col-md-8 col-sm-8 col-xs-12 row flex-column'
                               subtext="We're turning our experience into actionable insights on engineering, design, process and strategy."/>
          <section className="post-body blog">
            <div className="container">
              <div className="row">
                {data.allMdx.edges.map(({node}) => (
                  <BlogPostCard key={node.id} postDetails={node.frontmatter} timeToRead={node.timeToRead}/>
                ))}
              </div>
            </div>
          </section>
        </>
      )}
      <HowCanWeHelpBanner/>
      <Footer/>
    </Layout>
  )
}

export const query = graphql`
    query BlogHomeQuery($id: String!) {
        allMdx(
            filter: { frontmatter: { key: { eq: "blog-post" } } }
            sort: { fields: [frontmatter___publishedAt, frontmatter___slug], order: [DESC, DESC] }) {
            edges {
                node {
                    id
                    timeToRead
                    frontmatter {
                        key
                        publishedAt
                        slug
                        title
                        category
                        headerImage {
                            childImageSharp {
                                gatsbyImageData
                            }
                        }
                        author
                        shortDescription
                    }
                }
            }
        }
        mdx(id: { eq: $id }) {
            id
            body
            timeToRead
            excerpt(pruneLength: 160)
            frontmatter {
                key
                slug
                title
                category
                author
                publishedAt
                shortDescription
                headerImage {
                    childImageSharp {
                        gatsbyImageData(width: 800)
                    }
                }
            }
        }
    }
`;
